const D = { scale:1, energy:.7, speed:1, density:.5, hue:45, x:.5, y:.72, style:'maritime', seed:0, act:'sweep' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const TAU = 6.28318530718, u = Math.min(width, height);
const st = P.style;
const bx = P.x*width, baseY = P.y*height;                 // tower base (waterline)
const th = u*0.5*P.scale;                                  // tower height
const topY = baseY - th;
const tw = u*0.11*P.scale;                                 // base half-width
const twT = tw*0.42;                                       // top half-width
const H = P.hue % 360;
// palette by style
let ink, band1, band2, beamH, fogH, seaH;
if (st==='chart'){ ink=[192,72,86]; band1=[192,40,20]; band2=[192,20,40]; beamH=192; fogH=192; seaH=200; }
else if (st==='noir'){ ink=[210,6,92]; band1=[210,4,10]; band2=[210,3,30]; beamH=45; fogH=210; seaH=215; }
else if (st==='riso'){ ink=[338,70,92]; band1=[338,60,80]; band2=[210,70,80]; beamH=48; fogH=210; seaH=214; }
else if (st==='thermal'){ ink=[20,90,95]; band1=[8,90,40]; band2=[40,95,80]; beamH=50; fogH=260; seaH=250; }
else { ink=[H,10,95]; band1=[0,72,80]; band2=[0,0,96]; beamH=H; fogH=205; seaH=210; }
const wire = (st==='chart');
// ---- draw sea fog behind tower (drifting, real-time floor) ----
blendMode(BLEND); noStroke();
for (let i=0;i<7;i++){
  const fy = baseY - u*0.02 + Math.sin(K.t*0.35 + i*1.3)*u*0.015 + i*u*0.012;
  const span = width*1.4;
  const fxp = ((fr(i+40)*span + K.t*(9+i*4)*(0.5+P.speed*0.5)) % span) - width*0.2;
  const fa = (wire?6:13) * (0.6 + 0.4*Math.sin(K.t*0.5+i));
  fill(fogH, wire?30:22, wire?50:70, Math.max(2,fa));
  ellipse(fxp, fy, width*0.5, u*0.14);
}
// ---- rotating beam (continuous seconds-based, never rephases at 8s) ----
const lampY = topY + th*0.06;
let beat = K.beat; if (S.lb==null || beat < S.lb) S.lb = beat; S.lb = beat;
const rot = K.t * (0.55*P.speed) + fr(7)*TAU;            // radians, continuous
const beamLen = Math.max(width,height)*1.2;
const spread = 0.10 + 0.03*Math.sin(K.t*1.7);
const bright = (0.5 + 0.5*K.swell)*P.energy + (A.bass||0)*0.5;
const facing = Math.max(0, Math.sin(rot));               // brightest when sweeping toward viewer
blendMode(ADD);
// two opposite lobes
for (let s=0;s<2;s++){
  const ang = rot + s*Math.PI;
  const face = Math.max(0.06, Math.abs(Math.sin(ang)));
  if (wire){
    stroke(beamH, 50, 90, 30+face*40); strokeWeight(1); noFill();
    for (let r=0;r<7;r++){ const a=ang-spread+ (2*spread)*r/6; const dsh = beamLen*(0.2+0.8*((r+K.t)%1)); line(bx,lampY, bx+Math.cos(a)*dsh, lampY+Math.sin(a)*dsh); }
    noStroke();
  } else {
    noStroke();
    for (let g=0;g<3;g++){
      const sp = spread*(1+g*0.6), al = (10+bright*22)*face/(1+g*1.1);
      fill(beamH, st==='noir'?4:40, 100, al);
      triangle(bx,lampY, bx+Math.cos(ang-sp)*beamLen, lampY+Math.sin(ang-sp)*beamLen, bx+Math.cos(ang+sp)*beamLen, lampY+Math.sin(ang+sp)*beamLen);
    }
  }
}
blendMode(BLEND);
// ---- tower body (drawn each frame; few shapes) ----
noStroke();
// silhouette trapezoid
const tl = bx-tw, tr = bx+tw, ttl = bx-twT, ttr = bx+twT;
if (wire){
  stroke(ink[0],ink[1],ink[2],85); strokeWeight(Math.max(1,u*0.0035)); noFill();
  quad(tl,baseY, tr,baseY, ttr,topY+th*0.12, ttl,topY+th*0.12);
  // horizontal course lines
  for (let b=1;b<9;b++){ const t=b/9; const y=baseY-(th*0.88)*t; const wL=tw+(twT-tw)*t; line(bx-wL,y,bx+wL,y); }
  // schematic dimension tick
  stroke(ink[0],40,60,50); line(tr+u*0.03,baseY, tr+u*0.03, topY); line(tr+u*0.02,baseY,tr+u*0.04,baseY); line(tr+u*0.02,topY,tr+u*0.04,topY);
  noFill();
} else {
  // painted stripes
  const nBand = 5;
  for (let b=0;b<nBand;b++){
    const t0=b/nBand, t1=(b+1)/nBand;
    const y0=baseY-(th*0.88)*t0, y1=baseY-(th*0.88)*t1;
    const wl0=tw+(twT-tw)*t0, wl1=tw+(twT-tw)*t1;
    const c = (b%2===0)?band1:band2;
    fill(c[0],c[1],c[2]*(0.8+0.2*Math.sin(b)));
    quad(bx-wl0,y0, bx+wl0,y0, bx+wl1,y1, bx-wl1,y1);
  }
  // shading on left for form (chiaroscuro esp. noir)
  fill(band1[0], band1[1], 0, st==='noir'?55:28);
  quad(bx-tw,baseY, bx-tw*0.35,baseY, bx-twT*0.35,topY+th*0.12, bx-twT,topY+th*0.12);
}
// gallery + lantern room
const galY = topY + th*0.12;
fill(wire?0:200, wire?0:6, wire?0:14, wire?0:100);
if (wire){ stroke(ink[0],ink[1],ink[2],85); noFill(); }
rect(bx-twT*1.5, galY-u*0.012, twT*3, u*0.024, 2);
// lantern glass
const lampGlow = 60 + 40*Math.sin(K.t*3.2) + facing*40 + (A.rms||0)*60;
if (!wire){ noStroke();
  drawingContext.shadowColor = color(beamH,50,100,90).toString(); drawingContext.shadowBlur = u*0.05*(0.5+P.energy);
  fill(beamH, st==='noir'?8:45, Math.min(100,lampGlow)); ellipse(bx, lampY, twT*2.1, th*0.13);
  drawingContext.shadowBlur = 0;
  // cap
  fill(band1[0], band1[1], band1[2]*0.5); triangle(bx-twT*1.4, galY-u*0.012, bx+twT*1.4, galY-u*0.012, bx, galY-u*0.07);
} else {
  stroke(ink[0],ink[1],ink[2],90); noFill(); ellipse(bx,lampY,twT*2.1,th*0.13);
  line(bx-twT*1.4, galY-u*0.012, bx, galY-u*0.07); line(bx+twT*1.4, galY-u*0.012, bx, galY-u*0.07);
}
// ---- waves + splash at base (real-time roll + beat splash) ----
noStroke(); blendMode(BLEND);
const seaTop = baseY;
for (let l=0;l<3;l++){
  const yb = seaTop + l*u*0.02 + u*0.005;
  const amp = u*0.012*(1+l*0.4), ph = K.t*(1.1+l*0.5)*(0.5+P.speed*0.5);
  beginShape();
  fill(seaH, st==='noir'?8:38, (st==='thermal'?30:22)+l*6, wire?40:80);
  vertex(0, height);
  for (let xx=0; xx<=width; xx+=Math.max(10,width/48)){
    const yy = yb + Math.sin(xx*0.012 + ph)*amp + Math.sin(xx*0.03 - ph*1.4)*amp*0.4;
    vertex(xx, yy);
  }
  vertex(width, height); endShape(CLOSE);
}
// splash at tower base on beat
const splash = K.pulse*P.energy + (A.bass||0)*0.6;
if (splash > 0.08){ blendMode(ADD); noStroke();
  const n = Math.round(6 + P.density*14);
  for (let i=0;i<n;i++){ const a = -Math.PI*(0.15+0.7*fr(i+Math.floor(K.beat))); const sp = splash*u*0.09*(0.5+fr(i+3)); const px=bx+Math.cos(a)*sp*(fr(i)*2-1)*1.6; const py=seaTop-Math.abs(Math.sin(a))*sp; fill(seaH, 10, 100, 40*splash); ellipse(px,py, u*0.01*(0.5+fr(i+9)), u*0.01); }
  blendMode(BLEND);
}
drawingContext.shadowBlur = 0; blendMode(BLEND);
